<?php require_once __DIR__.'/../includes/auth.php'; $pageTitle='Add category'; $base='/shop-inventory-management'; $name='';$description='';$error=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$description=trim($_POST['description']??'');if($name==='')$error='Category name is required.';else{try{$s=$pdo->prepare('INSERT INTO categories(name,description) VALUES(?,?)');$s->execute([$name,$description?:null]);flash('success','Category added successfully.');redirect('index.php');}catch(PDOException $e){$error=$e->getCode()==='23000'?'That category name already exists.':'Could not save category.';}}} require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php'; ?>
<div class="page-heading"><div><h1>Add category</h1><p>Create a new product category.</p></div><a class="btn" href="index.php">← Back</a></div><div class="panel form-panel"><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Category name *<input name="name" maxlength="100" required value="<?=e($name)?>"></label><label>Description<textarea name="description" rows="4"><?=e($description)?></textarea></label><div class="form-actions"><button class="btn primary">Save category</button><a class="btn" href="index.php">Cancel</a></div></form></div><?php require __DIR__.'/../includes/footer.php'; ?>
